-- 228 — source-backed public company discovery directory.
-- Wikidata-derived records are discovery metadata, not financial or diligence claims.
CREATE TABLE IF NOT EXISTS research_company_directory (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  uid TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  website TEXT NOT NULL,
  country TEXT,
  founded_year INTEGER,
  sector TEXT,
  source_name TEXT NOT NULL DEFAULT 'Wikidata',
  source_url TEXT NOT NULL,
  source_license TEXT NOT NULL DEFAULT 'CC0 (Wikidata data); website links are references',
  as_of TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_research_company_directory_name ON research_company_directory(name);
CREATE INDEX IF NOT EXISTS idx_research_company_directory_country ON research_company_directory(country);
